/**
 * Utilitaire de logging conditionnel
 * Les logs ne s'affichent qu'en développement
 */

const isDevelopment = process.env.NODE_ENV === 'development';

export const logger = {
  log: (...args) => {
    if (isDevelopment) {
      console.log(...args);
    }
  },

  info: (...args) => {
    if (isDevelopment) {
      console.info(...args);
    }
  },

  warn: (...args) => {
    if (isDevelopment) {
      console.warn(...args);
    }
  },

  error: (...args) => {
    // Les erreurs sont toujours logguées mais sans stack trace sensible en prod
    if (isDevelopment) {
      console.error(...args);
    } else {
      console.error('Une erreur est survenue. Consultez les logs serveur pour plus de détails.');
    }
  },

  debug: (...args) => {
    if (isDevelopment && process.env.REACT_APP_DEBUG === 'true') {
      console.log('[DEBUG]', ...args);
    }
  }
};

export default logger;
